CREATE TABLE media_technical_metadata (media_file_id TEXT PRIMARY KEY REFERENCES media_files(id) ON DELETE CASCADE, file_size INTEGER NOT NULL, modified_at TEXT NOT NULL, container TEXT, duration_ms INTEGER, overall_bitrate INTEGER, video_codec TEXT, video_profile TEXT, width INTEGER, height INTEGER, frame_rate REAL, video_bitrate INTEGER, bit_depth INTEGER, hdr_type TEXT, audio_codec TEXT, audio_channels INTEGER, audio_sample_rate INTEGER, audio_bitrate INTEGER, audio_language TEXT, audio_tracks TEXT NOT NULL DEFAULT '[]', subtitle_tracks TEXT NOT NULL DEFAULT '[]', analyzed_at TEXT NOT NULL);
CREATE TABLE playback_sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), media_item_id TEXT NOT NULL REFERENCES media_items(id), media_file_id TEXT NOT NULL REFERENCES media_files(id), episode_id TEXT REFERENCES tv_episodes(id), mode TEXT NOT NULL, quality_profile TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '[]', stream_token_hash TEXT NOT NULL, started_at TEXT NOT NULL, last_activity_at TEXT NOT NULL, position_ms INTEGER NOT NULL DEFAULT 0, duration_ms INTEGER NOT NULL DEFAULT 0, client_id TEXT, client_name TEXT, ip_address TEXT, status TEXT NOT NULL, pipeline_key TEXT, bytes_served INTEGER NOT NULL DEFAULT 0, buffer_events INTEGER NOT NULL DEFAULT 0, ended_at TEXT);
CREATE TABLE playback_progress (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, media_item_id TEXT NOT NULL REFERENCES media_items(id) ON DELETE CASCADE, episode_id TEXT REFERENCES tv_episodes(id) ON DELETE CASCADE, content_key TEXT NOT NULL, position_ms INTEGER NOT NULL, duration_ms INTEGER NOT NULL, percentage REAL NOT NULL, updated_at TEXT NOT NULL, completed_at TEXT, UNIQUE(user_id, content_key));
CREATE TABLE playback_history (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, media_item_id TEXT NOT NULL REFERENCES media_items(id) ON DELETE CASCADE, episode_id TEXT REFERENCES tv_episodes(id) ON DELETE CASCADE, content_key TEXT NOT NULL, started_at TEXT NOT NULL, last_watched_at TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0, watch_time_ms INTEGER NOT NULL DEFAULT 0, session_count INTEGER NOT NULL DEFAULT 1, UNIQUE(user_id, content_key));
CREATE INDEX idx_playback_sessions_user ON playback_sessions(user_id,last_activity_at);
CREATE INDEX idx_playback_progress_user ON playback_progress(user_id,updated_at);
CREATE INDEX idx_playback_history_user ON playback_history(user_id,last_watched_at);
